<?php
namespace Tests\Unit; use PHPUnit\Framework\TestCase;
final class NormalizedDataDtoContractTest extends TestCase { public function test_dtos_are_readonly_and_detached():void{foreach(['SharedDataResult','ServerStatusData','MetricsData'] as $n){$s=file_get_contents(dirname(__DIR__,2).'/src/Data/'.$n.'.php');self::assertStringContainsString('final readonly class',$s);self::assertStringNotContainsString('Eloquent',$s);}} public function test_safe_public_serialization_excludes_internal_metadata():void{$s=file_get_contents(dirname(__DIR__,2).'/src/Data/SharedDataResult.php');self::assertStringNotContainsString("'provider_type_id'=>",substr($s,strpos($s,'public function publicArray'),strpos($s,'public function internalArray')-strpos($s,'public function publicArray')));self::assertStringContainsString("'provider_type_id'=>",$s);} }
